@@ -4,6 +4,7 @@
 export class Router {
   constructor() {
     this.routes = []
+    this.middlewares = []
   }

   add(method, pattern, handler) {
@@ -28,6 +29,53 @@ export class Router {
     return this.add('POST', pattern, handler)
   }

+  use(fn) {
+    this.middlewares.push(fn)
+    return this
+  }
+
+  async dispatch(ctx = {}) {
+    ctx.params ??= {}
+    ctx.state ??= {}
+    try {
+      const pathname = new URL(ctx.path ?? ctx.url ?? '/', 'http://localhost').pathname
+      const match = this.match(ctx.method, pathname)
+      const handler = match ? match.handler : null
+      if (match) ctx.params = match.params
+
+      const runHandler = async (c) => {
+        if (!handler) return { status: 404, body: { error: 'Not found' } }
+        return await handler(c)
+      }
+
+      const exec = async (i, c) => {
+        if (i >= this.middlewares.length) return runHandler(c)
+        const mw = this.middlewares[i]
+        let called = false
+        const next = async () => {
+          called = true
+          return exec(i + 1, c)
+        }
+        const res = await mw(c, next)
+        if (res !== undefined) return res
+        if (!called) return undefined
+        return undefined
+      }
+
+      const out = await exec(0, ctx)
+      if (out !== undefined) return out
+      return await runHandler(ctx)
+    } catch (err) {
+      const resp = typeof err?.status === 'number'
+        ? { status: err.status, body: { error: err.message } }
+        : { status: 500, body: { error: 'Internal error' } }
+      if (ctx && ctx.state && ctx.state.requestId) {
+        resp.headers = { ...(resp.headers ?? {}), 'x-request-id': ctx.state.requestId }
+      }
+      return resp
+    }
+  }
+
