--- a/src/server.js
+++ b/src/server.js
@@ -11,6 +11,38 @@ import { formatCurrency } from './format.js'
 export function createApp(inventory = Inventory.fromFile()) {
   const router = new Router()

+  // request id middleware
+  router.use(async (ctx, next) => {
+    const { headers = {} } = ctx
+    const id = (globalThis.crypto && crypto.randomUUID && crypto.randomUUID()) || String(Date.now()) + Math.random()
+    ctx.state.requestId = id
+    let res
+    try {
+      res = await next()
+      return res
+    } finally {
+      // attach header to any response object returned by downstream
+      if (res) {
+        res.headers = { ...(res.headers ?? {}), 'x-request-id': id }
+      }
+      // errors will be handled by router.dispatch which will also attach header from ctx.state
+    }
+  })
+
+  // api-key auth middleware
+  router.use(async (ctx, next) => {
+    const method = ctx.method
+    const safeMethods = ['GET']
+    const protectedMethods = ['POST', 'PUT', 'PATCH', 'DELETE']
+    const apiKeysEnv = process.env.API_KEYS
+    if (!apiKeysEnv) return await next()
+    if (!protectedMethods.includes(method)) return await next()
+    const allowed = apiKeysEnv.split(',').map(s => s.trim()).filter(Boolean)
+    const key = (ctx.headers && ctx.headers['x-api-key']) ?? (ctx.headers && ctx.headers['X-API-Key'])
+    if (allowed.includes(key)) return await next()
+    return { status: 401, body: { error: 'Unauthorized' } }
+  })
+
   router.get('/health', () => ({ status: 200, body: { status: 'ok' } }))

   router.get('/books', () => ({ status: 200, body: inventory.list() }))
