-    try {
-      return await match.handler({ params: match.params, query: url.searchParams, body: req.body ?? {} })
-    } catch (err) {
-      return { status: 500, body: { error: err.message } }
+    const ctx = {
+      method: req.method,
+      path: url.pathname,
+      url: req.url,
+      query: url.searchParams,
+      headers: req.headers ?? {},
+      body: req.body ?? {},
+      state: {},
     }
+    return router.dispatch(ctx)
   }
